SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- Normalizar nombres oficiales de comunidades
UPDATE comunidades SET nombre = CASE id
  WHEN 1 THEN 'Andalucía'
  WHEN 2 THEN 'Aragón'
  WHEN 3 THEN 'Principado de Asturias'
  WHEN 4 THEN 'Illes Balears'
  WHEN 5 THEN 'Canarias'
  WHEN 6 THEN 'Cantabria'
  WHEN 7 THEN 'Castilla-La Mancha'
  WHEN 8 THEN 'Castilla y León'
  WHEN 9 THEN 'Cataluña'
  WHEN 10 THEN 'Comunitat Valenciana'
  WHEN 11 THEN 'Extremadura'
  WHEN 12 THEN 'Galicia'
  WHEN 13 THEN 'Comunidad de Madrid'
  WHEN 14 THEN 'Región de Murcia'
  WHEN 15 THEN 'Comunidad Foral de Navarra'
  WHEN 16 THEN 'País Vasco / Euskadi'
  WHEN 17 THEN 'La Rioja'
  WHEN 18 THEN 'Ceuta'
  WHEN 19 THEN 'Melilla'
  ELSE nombre END;

INSERT IGNORE INTO comunidades (id, nombre) VALUES
  (18, 'Ceuta'),
  (19, 'Melilla');

-- Normalizar nombres oficiales de provincias
UPDATE provincias SET nombre = CASE id
  WHEN 1 THEN 'Almería'
  WHEN 2 THEN 'Cádiz'
  WHEN 3 THEN 'Córdoba'
  WHEN 4 THEN 'Granada'
