  WHEN 47 THEN 'Álava/Araba'
  WHEN 48 THEN 'Bizkaia'
  WHEN 49 THEN 'Gipuzkoa'
  WHEN 50 THEN 'La Rioja'
  WHEN 51 THEN 'Ceuta'
  WHEN 52 THEN 'Melilla'
  ELSE nombre END;

INSERT IGNORE INTO provincias (id, nombre, comunidad_id) VALUES
