-- Normalizar categorías almacenadas
UPDATE anuncios SET categoria = 'cultura' WHERE LOWER(categoria) = 'cultura';
UPDATE anuncios SET categoria = 'cultura' WHERE categoria = 'Cultura';
UPDATE anuncios SET categoria = 'tecnologia' WHERE categoria = 'tecnología';
UPDATE anuncios SET categoria = 'otros' WHERE categoria = '' OR categoria IS NULL;

-- Sincronizar nombres territorial en anuncios existentes
UPDATE anuncios a
JOIN comunidades c ON a.comunidad_id = c.id
JOIN provincias p ON a.provincia_id = p.id
SET a.comunidad_autonoma = c.nombre, a.provincia = p.nombre;

